import{_ as e,o as n,c as l,ag as r}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"为什么相机生产链坚持单一 Owner，并拒绝静默 Runtime Fallback","description":"复盘 RK3588 相机流水线从多条并行路径收敛为单一 owner、typed graph、direct consumer 与显式失败的架构选择","frontmatter":{"title":"为什么相机生产链坚持单一 Owner，并拒绝静默 Runtime Fallback","description":"复盘 RK3588 相机流水线从多条并行路径收敛为单一 owner、typed graph、direct consumer 与显式失败的架构选择","tags":["RK3588","Camera Pipeline","DMA-BUF","Architecture","架构选择"],"date":"2026/07/20"},"headers":[],"relativePath":"linux/camera-single-owner-no-runtime-fallback.md","filePath":"linux/camera-single-owner-no-runtime-fallback.md","lastUpdated":1784519165000}'),i={name:"linux/camera-single-owner-no-runtime-fallback.md"};function t(s,a,p,o,c,u){return n(),l("div",null,[...a[0]||(a[0]=[r(`<h1 id="为什么相机生产链坚持单一-owner-并拒绝静默-runtime-fallback" tabindex="-1">为什么相机生产链坚持单一 Owner，并拒绝静默 Runtime Fallback <a class="header-anchor" href="#为什么相机生产链坚持单一-owner-并拒绝静默-runtime-fallback" aria-label="Permalink to &quot;为什么相机生产链坚持单一 Owner，并拒绝静默 Runtime Fallback&quot;">​</a></h1><p>相机系统最危险的架构不是某条链路性能差，而是两条链路都“似乎能工作”。当采集、畸变校正、ROS 发布和算法接入分别保留自己的 owner、buffer pool 与恢复逻辑后，系统会进入一种很难证明正确的状态：资源是谁占的、时间戳来自哪里、失败后切到了哪条路，都不再清楚。</p><p>所以这次架构改造的核心不是换一个更快的 API，而是把生产链收敛为单一 owner，并让失败明确发生。</p><h2 id="旧思路的问题-每个-consumer-都能拿到图" tabindex="-1">旧思路的问题：每个 consumer 都能拿到图 <a class="header-anchor" href="#旧思路的问题-每个-consumer-都能拿到图" aria-label="Permalink to &quot;旧思路的问题：每个 consumer 都能拿到图&quot;">​</a></h2><p>早期系统里，相机数据可以经过 ROS topic、共享内存、兼容 publisher 或独立采集节点到达算法。每条路径单独看都合理，但组合起来会产生几个问题：</p><ul><li>多个进程可能争抢同一视频设备；</li><li>相同像素被重复转换和复制；</li><li>不同路径各自解释曝光、PTS 和 group timestamp；</li><li>恢复时无法确认旧进程是否仍持有设备或 buffer；</li><li>A/B 测量可能把两个版本的进程混在一起。</li></ul><p>这类问题往往不会在编译阶段出现，而是在重启、降级或高负载下变成偶发故障。</p><h2 id="最终架构-一个-owner-一次采集-多路消费" tabindex="-1">最终架构：一个 owner，一次采集，多路消费 <a class="header-anchor" href="#最终架构-一个-owner-一次采集-多路消费" aria-label="Permalink to &quot;最终架构：一个 owner，一次采集，多路消费&quot;">​</a></h2><p>生产架构被收敛为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>V4L2 / native capture owner</span></span>
<span class="line"><span>  → typed frame bundle</span></span>
<span class="line"><span>  → trigger / exposure timing matcher</span></span>
<span class="line"><span>  → hardware fisheye / transform</span></span>
<span class="line"><span>  → NV12 stereo atlas</span></span>
<span class="line"><span>  ├─ direct algorithm consumers</span></span>
<span class="line"><span>  ├─ encoder / SDK consumers</span></span>
<span class="line"><span>  └─ compatibility ROS adapter</span></span></code></pre></div><p>runtime 是唯一相机 owner。Core 不依赖 ROS，负责 <code>FrameHandle</code>、<code>BufferLease</code>、时间和布局合同；RK3588 adapter 持有 V4L2、DMA-BUF、RGA、OpenCL 与 MPP 的平台细节；ROS bridge 只做兼容发布，不拥有采集链。</p><p>这让“谁负责什么”变得可验证：</p><ul><li>capture owner 决定 buffer 何时进入和离开驱动；</li><li>timing matcher 决定哪些帧属于同一组；</li><li>executor 产出带 layout 的执行结果；</li><li>consumer 只消费 typed contract；</li><li>compatibility adapter 可以关闭，不反向定义生产主链。</li></ul><h2 id="为什么不做静默-runtime-fallback" tabindex="-1">为什么不做静默 runtime fallback <a class="header-anchor" href="#为什么不做静默-runtime-fallback" aria-label="Permalink to &quot;为什么不做静默 runtime fallback&quot;">​</a></h2><p>“OpenCL 失败就自动切 CPU”听起来很稳健，但生产上会制造更隐蔽的问题：</p><ol><li>服务仍然 active，实际性能和延迟已经完全改变；</li><li>CPU fallback 可能让温度、帧率和其他实时任务一起退化；</li><li>指标只看到业务仍有输出，却看不到系统已进入非目标架构；</li><li>故障无法复现，因为重启后又可能回到硬件路径。</li></ol><p>因此生产主链坚持：平台能力或配置不满足时显式失败。需要回滚时，部署旧版本或切换明确的 legacy mode，而不是在同一个进程里悄悄换执行路径。</p><p><strong>Runtime fallback 和版本回滚不是一回事。</strong> 前者改变运行语义却可能隐藏故障，后者是可观测、可审计的运维动作。</p><h2 id="一次踩坑-把目标能力写成了已完成能力" tabindex="-1">一次踩坑：把目标能力写成了已完成能力 <a class="header-anchor" href="#一次踩坑-把目标能力写成了已完成能力" aria-label="Permalink to &quot;一次踩坑：把目标能力写成了已完成能力&quot;">​</a></h2><p>架构文档第一次整理时，direct consumer 已经存在，很容易顺手写成“ROS BGR 路径已经移除”。但源码检查发现兼容 publisher 仍然会做 NV12 到 BGR、mmap/read 和消息复制。</p><p>这不是措辞问题，而是证据边界问题。修正后的文档明确区分：</p><ul><li><strong>已实现</strong>：typed graph、单一 owner、DMA-BUF fan-out、direct consumer；</li><li><strong>兼容路径仍存在</strong>：ROS BGR publisher；</li><li><strong>待验证</strong>：subscriber-aware 关闭策略和新的板端 CPU A/B。</li></ul><p>架构说明如果把目标状态写成当前事实，后续性能分析就会从错误基线出发。</p><h2 id="队列为什么也是架构合同" tabindex="-1">队列为什么也是架构合同 <a class="header-anchor" href="#队列为什么也是架构合同" aria-label="Permalink to &quot;队列为什么也是架构合同&quot;">​</a></h2><p>共享 buffer 不代表所有 consumer 必须同步阻塞。不同支路采用不同队列语义：</p><ul><li>source 到 matcher 使用有界队列，满时丢最旧帧；</li><li>实时 consumer 使用 <code>Latest(1)</code>，保留一帧执行中和一帧最新待处理；</li><li>每条支路有独立 worker，慢 consumer 不阻塞整个 graph。</li></ul><p>这不是简单的性能参数。队列策略决定系统在过载时是增加延迟、丢旧数据，还是拖死生产者，必须成为显式合同。</p><p>停机顺序同样不能靠感觉：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Quiesce producer</span></span>
<span class="line"><span>  → Drain in-flight work</span></span>
<span class="line"><span>  → Disconnect consumers</span></span>
<span class="line"><span>  → Stop platform backend</span></span></code></pre></div><p>只等 queue empty 就停 backend 会留下竞态，因为 producer 仍可能继续投递；直接 disconnect 也不能强杀正在执行的 callback。</p><h2 id="为什么这种设计更容易迁移平台" tabindex="-1">为什么这种设计更容易迁移平台 <a class="header-anchor" href="#为什么这种设计更容易迁移平台" aria-label="Permalink to &quot;为什么这种设计更容易迁移平台&quot;">​</a></h2><p>跨平台复用的不是 V4L2 或 OpenCL 代码，而是 frame、buffer、time、graph 和 consumer contract。迁移到另一颗 SoC 时，应该替换 capture、cache/fence、图像加速、编码和 NPU adapter，而不是复制整套 runtime。</p><p>迁移第一步也不是写 backend，而是 capability probe：</p><ul><li>能否导出或导入共享 buffer；</li><li>cache sync 与 fence 怎样表达；</li><li>多相机同步由谁保证；</li><li>pool 深度和 release route 是否可控；</li><li>硬件畸变校正与 native tensor 能否接入。</li></ul><p>能力不成立就明确失败，重新评估架构；不能先写一个 CPU fallback，把平台差异藏起来。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>单一 owner 的价值不是“代码更漂亮”，而是让设备、buffer、时间和失败都只有一份权威解释。拒绝静默 fallback，也不是追求激进，而是避免系统在最需要诊断时继续假装健康。</p><p>相机生产链最终要证明的，不只是有图，而是这张图从哪里来、经过什么硬件、由谁持有、何时可复用，以及能力不足时为什么会明确失败。</p><p>延伸阅读：<a href="/linux/rk3588-camera-pipeline">RK3588 高性能相机流水线</a>、<a href="/linux/dmabuf-ownership-contract">跨进程 DMA-BUF 所有权合同</a>。</p>`,39)])])}const h=e(i,[["render",t]]);export{m as __pageData,h as default};
